{"tool": "write_file", "args": {"content": """"Ops script: verify the cycle-2 disbursement. Read-only.

Run from the Lifeline root:  python scripts/verify_cycle2.py

Checks that each currently eligible household has exactly one 60-dollar cycle-2
payment, and that no ineligible household appears in the payments or SMS outbox.
"""

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from eligibility.rules import is_eligible  # noqa: E402
from notifications.sms import sent_messages  # noqa: E402
from payments.receipts import receipts_for, total_paid  # noqa: E402
from payments.vouchers import payment_key, sent_payments  # noqa: E402
from registry.register import load_households  # noqa: E402

CYCLE = 2
AMOUNT = 60


def main() -> None:
    problems = []
    eligible = {h.id for h in load_households(active_only=True) if is_eligible(h)}
    paid_ids = {p.household_id for p in sent_payments()}

    for household_id in sorted(eligible):
        cycle2 = [p for p in sent_payments()
                  if p.household_id == household_id and p.key == payment_key(household_id, CYCLE)]
        if len(cycle2) != 1 or cycle2[0].amount != AMOUNT:
            problems.append(f"{household_id}: expected exactly one {AMOUNT}-dollar cycle-2 payment, "
                            f"got {[(p.amount, p.key) for p in cycle2]}")
        if total_paid(household_id) != AMOUNT:
            problems.append(f"{household_id}: total_paid is {total_paid(household_id)}, expected {AMOUNT}")
        print(receipts_for(household_id)[0] if receipts_for(household_id) else f"{household_id}: NO RECEIPT")

    for stray in sorted(paid_ids - eligible):
        problems.append(f"ineligible household {stray} was paid")
    for m in sent_messages():
        if m.template_id == "PAYMENT_SENT" and m.params.get("cycle") == CYCLE and m.household_id not in eligible:
            problems.append(f"ineligible household {m.household_id} got a cycle-2 SMS")

    if problems:
        print("PROBLEMS:")
        for p in problems:
            print(f"  {p}")
    else:
        print(f"OK: {len(eligible)} eligible households each paid {AMOUNT} dollars for cycle {CYCLE}, "
              f"no ineligible household paid")


if __name__ == "__main__":
    main()
